// Embeds a WGT .SPR file as base64 inside a plain <script> file, so the game
// also works when index.html is opened straight from disk (file:// cannot fetch()).
//
//   node tools/embed-spr.js assets/BEAK.SPR assets/beak.spr.js
//
const fs = require('fs');
const [, , src = 'assets/BEAK.SPR', out = 'assets/beak.spr.js'] = process.argv;
const b64 = fs.readFileSync(src).toString('base64');
fs.writeFileSync(out,
  '// Generated by tools/embed-spr.js from ' + src.replace(/\\/g, '/') + ' - do not edit by hand.\n' +
  'window.BEAK_SPR_BASE64 = "' + b64 + '";\n');
console.log('wrote', out, b64.length, 'chars');
